/**
 * Tier-2 numeric helpers for the calc DSL.
 *
 * Each builder is a thin typed wrapper over a wire `FUNC(...)` form.
 * Output brands mirror the Java test's behavior:
 *   - `round` returns NUMBER without places and DECIMAL with places.
 *   - `power`, `sqrt` return DECIMAL (fractional results possible).
 *   - `toNumber` coerces text → NUMBER.
 *   - `uuid` is nullary and returns a `uuid`-branded expression.
 */
import { coerce, makeComposedExpr, makeExpr } from "./runtime.js";
export function round(value, digits) {
    const v = coerce(value);
    if (digits === undefined) {
        return makeComposedExpr("number", [v], () => `ROUND(${v.toCalcString()})`);
    }
    if (!Number.isInteger(digits) || digits < 0) {
        throw new Error("calc.round: digits must be a non-negative integer literal.");
    }
    return makeComposedExpr(digits === 0 ? "number" : "decimal", [v], () => `ROUND(${v.toCalcString()}, ${digits})`);
}
// ---------------------------------------------------------------------------
// POWER — base^exponent, decimal output.
// ---------------------------------------------------------------------------
export function power(base, exponent) {
    const b = coerce(base);
    const e = coerce(exponent);
    return makeComposedExpr("decimal", [b, e], () => `POWER(${b.toCalcString()}, ${e.toCalcString()})`);
}
// ---------------------------------------------------------------------------
// SQRT — square root, decimal output. Server null-guards negatives.
// ---------------------------------------------------------------------------
export function sqrt(value) {
    const v = coerce(value);
    return makeComposedExpr("decimal", [v], () => `SQRT(${v.toCalcString()})`);
}
// ---------------------------------------------------------------------------
// VALUE (toNumber) — coerce text to numeric. Wire form is `VALUE(text)`.
// Renamed to `toNumber` in the EDK for parity with `toText`.
// ---------------------------------------------------------------------------
export function toNumber(value) {
    const v = coerce(value);
    return makeComposedExpr("number", [v], () => `VALUE(${v.toCalcString()})`);
}
// ---------------------------------------------------------------------------
// UUID — nullary generator, returns `uuid`-branded.
// ---------------------------------------------------------------------------
export function uuid() {
    return makeExpr("uuid", () => `UUID()`);
}
